from .cli import RemoteShell


def connect(switch_cls, hostname, username, password, port=None, timeout=None):
    """ Connect to a switch.

    Using the given switch class, credentials and address, create a connection
    to the switch.

    :param switch_cls: A subclass of Switch, or a callable with the same
        signature as Switch.__init__(), which will return an instance of
        Switch. This will be used to create apropriate Switch object.
    :param hostname: Hostname of the switch to connect to.
    :param username: Username for the switch CLI.
    :param password: Password for the switch CLI.
    :param port: (Optional) port on which the CLI is listening for
        incomming connections.
    :param timeout: (Optional) timeout used when connecting to the CLI,
        specified as a float. By default, no timeout is used.
    :returns: An instance of a given subclass of Switch.
    """

    shell = RemoteShell(hostname, username, password, port=port,
                        timeout=timeout)
    return switch_cls(shell)
